<?php
require __DIR__.'/app/bootstrap.php';$ctx=growth_seller_context('auctions');$u=$ctx['user'];if(!setting_bool('store_auction_enabled',true)){exit('Auctions are disabled.');}$uid=(int)$ctx['owner_id'];$msg=$err=null;store_auction_sync();if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$pid=(int)$_POST['product_id'];$q=db()->prepare("SELECT * FROM store_products WHERE id=? AND seller_user_id=? AND status='published'");$q->execute([$pid,$uid]);$p=$q->fetch();if(!$p)throw new RuntimeException('Published product required.');$start=(string)$_POST['starts_at'];$end=(string)$_POST['ends_at'];if(strtotime($end)<=strtotime($start))throw new RuntimeException('End time must be after start.');$sp=max(0,(float)$_POST['start_price']);$inc=max(.01,(float)$_POST['min_increment']);db()->prepare("INSERT INTO store_auctions(product_id,start_price,current_price,min_increment,starts_at,ends_at,status) VALUES(?,?,?,?,?,?,IF(?<=NOW(),'live','scheduled')) ON DUPLICATE KEY UPDATE start_price=VALUES(start_price),current_price=GREATEST(current_price,VALUES(start_price)),min_increment=VALUES(min_increment),starts_at=VALUES(starts_at),ends_at=VALUES(ends_at),status=IF(VALUES(starts_at)<=NOW(),'live','scheduled'),winner_user_id=NULL")->execute([$pid,$sp,$sp,$inc,$start,$end,$start]);db()->prepare("UPDATE store_products SET sale_mode='auction',price=? WHERE id=? AND seller_user_id=?")->execute([$sp,$pid,$uid]);$msg='Auction saved.';}catch(Throwable $e){$err=$e->getMessage();}}$q=db()->prepare("SELECT a.*,p.title,p.slug,(SELECT COUNT(*) FROM store_auction_bids b WHERE b.auction_id=a.id) bid_count FROM store_auctions a JOIN store_products p ON p.id=a.product_id WHERE p.seller_user_id=? ORDER BY a.id DESC");$q->execute([$uid]);$auctions=$q->fetchAll();$q=db()->prepare("SELECT id,title FROM store_products WHERE seller_user_id=? AND status='published' ORDER BY title");$q->execute([$uid]);$products=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seller Auctions</title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"></head><body class="lc-page"><header class="lc-public-header"><div class="lt-shell"><a class="lc-public-brand" href="/seller.php">Seller Center</a><nav class="lc-public-nav"><a href="/shopkeeper-products.php">Products</a><a href="/shopkeeper-orders.php">Orders</a><a href="/shopkeeper-auctions.php">Auctions</a></nav></div></header><section class="shop-section"><div class="lt-shell checkout-grid"><section class="shop-panel"><h2>Your Auctions</h2><?php foreach($auctions as $a):?><div style="padding:12px 0;border-bottom:1px solid #e2e8f0"><b><?=e($a['title'])?></b><span class="order-status" style="float:right"><?=e($a['status'])?></span><p>Current Rs <?=e(number_format((float)$a['current_price'],0))?> · <?=e($a['bid_count'])?> bids · ends <?=e(date('d M h:i A',strtotime($a['ends_at'])))?></p><a target="_blank" href="/product.php?slug=<?=urlencode($a['slug'])?>">View Auction</a></div><?php endforeach;?></section><aside class="shop-panel"><h2>Create / Update Auction</h2><?php if($msg):?><div style="color:#166534"><?=e($msg)?></div><?php endif;?><?php if($err):?><div style="color:#991b1b"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Published Product</label><select name="product_id"><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['title'])?></option><?php endforeach;?></select><label>Starting Price</label><input type="number" step="0.01" name="start_price" required><label>Min Bid Increment</label><input type="number" step="0.01" name="min_increment" value="100"><label>Starts</label><input type="datetime-local" name="starts_at" required><label>Ends</label><input type="datetime-local" name="ends_at" required><button class="cv-primary-btn" style="border:0;margin-top:12px">Save Auction</button></form></aside></div></section></body></html>
